// ---- language picker (shared by every page) ----
;(() => {
  const NAMES = { en: 'English', ar: 'العربية', es: 'Español', fr: 'Français', de: 'Deutsch', pt: 'Português', ru: 'Русский', zh: '中文', ja: '日本語', ko: '한국어', hi: 'हिन्दी', tr: 'Türkçe', id: 'Bahasa Indonesia' }
  const RTL = ['ar']
  const D = window.KH_I18N || {}
  const langs = ['en', ...Object.keys(NAMES).filter(l => l !== 'en' && D[l])]
  const saved = (() => { try { return localStorage.getItem('kh-lang') } catch { return null } })()
  const guess = (navigator.languages || [navigator.language || 'en']).map(l => String(l).slice(0, 2).toLowerCase()).find(l => langs.includes(l))
  let lang = langs.includes(saved) ? saved : guess || 'en'
  window.khLang = () => lang
  window.khT = (key, fallback) => (lang !== 'en' && D[lang] && D[lang][key]) || fallback
  const apply = () => {
    document.documentElement.lang = lang
    document.documentElement.dir = RTL.includes(lang) ? 'rtl' : 'ltr'
    document.querySelectorAll('[data-i]').forEach(el => {
      if (el.dataset.en === undefined) el.dataset.en = el.textContent
      el.textContent = window.khT(el.dataset.i, el.dataset.en)
    })
    document.querySelectorAll('[data-ip]').forEach(el => {
      if (el.dataset.en === undefined) el.dataset.en = el.placeholder
      el.placeholder = window.khT(el.dataset.ip, el.dataset.en)
    })
    sel.value = lang
    dispatchEvent(new Event('kh-lang'))
  }
  const sel = document.createElement('select')
  sel.className = 'lang'; sel.setAttribute('aria-label', 'Language')
  sel.innerHTML = langs.map(l => `<option value="${l}">${NAMES[l]}</option>`).join('')
  sel.onchange = () => { lang = sel.value; try { localStorage.setItem('kh-lang', lang) } catch {} apply() }
  const links = document.querySelector('nav .links')
  if (links) links.append(sel)
  apply()
})()
